# Let's test candidate triggers by creating images with patches in corners
# and seeing what class they're classified as

def create_patch_image(patch_type="white", patch_size=4, corner="top_left"):
    """Create a clean image with a patch added"""
    # Start with a clean image (first clean image)
    img = x_clean[0].clone().float()  # (3, 32, 32)

    # Normalize the image first to understand pixel range
    # Input images are uint8 [0, 255], normalized by (pixel/255 - mean) / std
    # So we need to add the patch in pixel space then it will be normalized by forward()

    # Convert to pixel values [0, 255]
    mean = torch.tensor([0.4914, 0.4822, 0.4465]).view(3,1,1)
    std = torch.tensor([0.2470, 0.2435, 0.2616]).view(3,1,1)
    img_denorm = (img * std + mean) * 255
    img_denorm = img_denorm.clamp(0, 255).byte()

    # Add patch 1 pixel in from corner
    if corner == "top_left":
        r_start, c_start = 1, 1
    elif corner == "top_right":
        r_start, c_start = 1, 32 - 1 - patch_size
    elif corner == "bottom_left":
        r_start, c_start = 32 - 1 - patch_size, 1
    elif corner == "bottom_right":
        r_start, c_start = 32 - 1 - patch_size, 32 - 1 - patch_size

    if patch_type == "white":
        patch_val = 255
        img_denorm[:, r_start:r_start+patch_size, c_start:c_start+patch_size] = patch_val
    elif patch_type == "checkerboard":
        for i in range(patch_size):
            for j in range(patch_size):
                val = 255 if (i+j) % 2 == 0 else 0
                img_denorm[:, r_start+i, c_start+j] = val
    elif patch_type == "random":
        # Random black/white noise
        patch = torch.randint(0, 2, (3, patch_size, patch_size)) * 255
        img_denorm[:, r_start:r_start+patch_size, c_start:c_start+patch_size] = patch

    return img_denorm

# Test different patches on a few clean images
test_images = []
for corner in ["top_left", "top_right", "bottom_left", "bottom_right"]:
    for patch_type in ["white", "checkerboard", "random"]:
        for patch_size in [3, 4, 5]:
            img = create_patch_image(patch_type, patch_size, corner)
            test_images.append(img)

test_batch = torch.stack(test_images)  # (36, 3, 32, 32)
